submit.source:
on(release){
   BtnLine.enabled = false;
   Mc_Drag.enabled = false;
   _global.TryCount++;
   if(txtSlope.text == "-1")
   {
      _global.quizSection = false;
      play();
   }
   else
   {
      if(_global.TryCount == 1)
      {
         _global.WrongFeed = "Enter -1 in the equation for the slope. Try again.";
      }
      else
      {
         _global.WrongFeed = "Sorry, enter -1 in the equation for the slope.";
      }
      Mc_Feed_Popup1.txtFeed.text = _global.WrongFeed;
      Mc_Feed_Popup1._visible = true;
      Mc_Feed_Popup1.gotoAndPlay(2);
   }
}

close.source:
on(release){
   this._visible = false;
   this.gotoAndStop(2);
   _parent.BtnLine.enabled = true;
   _parent.Mc_Drag.enabled = true;
   if(_global.TryCount >= 2)
   {
      _global.quizSection = false;
      _parent.play();
   }
}

